use moloch_live_runtime::stream_recovery::{self,BudgetError,RecoveryBudget,MAXIMUM_CLOCK_MS};
#[path="../src/stream_connect_retry.rs"]mod retry;
use retry::*;
#[test]fn only_direct_native_dns_and_tcp_connect_faults_are_retryable(){for code in ["STREAM_DNS","STREAM_CONNECT"]{let f=ConnectionFailure::from_connect_error(code);assert!(f.is_retryable());assert_eq!(f.reason(),code);}for code in ["STREAM_HANDSHAKE","STREAM_JOIN_SEND","STREAM_TIMEOUT","STREAM_AUTH_URL","STREAM_HOST","LIVE_STREAM_JOIN_FAILED","STREAM_JOIN_REJECTED","STREAM_JSON","DURABILITY_FAILURE","LIVE_WRITE_NOT_CONFIRMED_NO_RETRY","STREAM_SOCKET_CLOSED"]{let f=ConnectionFailure::from_connect_error(code);assert!(!f.is_retryable(),"{code}");assert!(after_connect_failure(&RecoveryBudget::new(0).unwrap(),0,None,f).is_err());}}
#[test]fn untrusted_error_text_and_secret_urls_cannot_become_retry_authority(){let f=ConnectionFailure::from_connect_error("wss://fixture.invalid/?token=DO_NOT_KEEP");assert_eq!(f.to_string(),"STREAM_CONNECT_UNCLASSIFIED");let unrelated:Box<dyn std::error::Error>=Box::new(std::io::Error::other("STREAM_DNS"));assert!(unrelated.downcast_ref::<ConnectionFailure>().is_none());let deliberate:Box<dyn std::error::Error>=Box::new(ConnectionFailure::from_connect_error("STREAM_DNS"));assert!(deliberate.downcast_ref::<ConnectionFailure>().unwrap().is_retryable());}
#[test]fn startup_first_attempt_is_charged_without_mutating_unpersisted_input(){let b=RecoveryBudget::new(1000).unwrap();assert_eq!(next_attempt(&b,1000,None).unwrap(),1000);let admitted=prepare_attempt(&b,1000,None).unwrap();assert!(b.attempts().is_empty());assert_eq!(admitted.attempts(),&[1000]);assert_eq!(admitted.last_clock_ms(),1000);assert_eq!(next_attempt(&admitted,1000,Some(1000)).unwrap(),61000);}
#[test]fn failed_startup_connect_retries_share_the_same_three_attempt_budget(){let mut b=RecoveryBudget::new(0).unwrap();for now in [0,60000,120000]{if now>0{assert_eq!(after_connect_failure(&b,now,Some(now-60000),ConnectionFailure::from_connect_error("STREAM_DNS")).unwrap(),now);}b=prepare_attempt(&b,now,if now==0{None}else{Some(now-60000)}).unwrap();}assert_eq!(after_connect_failure(&b,180000,Some(120000),ConnectionFailure::from_connect_error("STREAM_CONNECT")),Err(RetryError::Exhausted));assert_eq!(b.attempts(),&[0,60000,120000]);}
#[test]fn restart_after_crash_does_not_erase_unminted_or_failed_connect_attempt(){let b=prepare_attempt(&RecoveryBudget::new(500).unwrap(),500,None).unwrap();let stored=serde_json::to_vec(&b).unwrap();let loaded:RecoveryBudget=serde_json::from_slice(&stored).unwrap();assert_eq!(next_attempt(&loaded,1000,None).unwrap(),60500);assert_eq!(prepare_attempt(&loaded,1000,None),Err(RetryError::TooSoon));assert_eq!(loaded,b);}
#[test]fn auth_marker_and_budget_wait_are_combined_not_reset(){let b=prepare_attempt(&RecoveryBudget::new(0).unwrap(),0,None).unwrap();assert_eq!(next_attempt(&b,10000,Some(5000)).unwrap(),65000);assert_eq!(prepare_attempt(&b,64000,Some(5000)),Err(RetryError::TooSoon));let next=prepare_attempt(&b,65000,Some(5000)).unwrap();assert_eq!(next.attempts(),&[0,65000]);}
#[test]fn failed_token_mint_already_charged_is_not_refunded_or_reclassified(){let b=prepare_attempt(&RecoveryBudget::new(0).unwrap(),0,None).unwrap();assert!(after_connect_failure(&b,1000,Some(0),ConnectionFailure::from_connect_error("COMPLETION_DURABILITY_UNCERTAIN")).is_err());assert_eq!(b.attempts(),&[0]);assert_eq!(prepare_attempt(&b,1000,Some(0)),Err(RetryError::TooSoon));}
#[test]fn active_three_attempt_window_stops_instead_of_waiting_ten_minutes(){let mut b=RecoveryBudget::new(0).unwrap();for n in [0,60000,120000]{b=prepare_attempt(&b,n,None).unwrap();}assert_eq!(next_attempt(&b,600000,None),Err(RetryError::Exhausted));assert_eq!(next_attempt(&b,600001,None).unwrap(),600001);let next=prepare_attempt(&b,600001,None).unwrap();assert_eq!(next.attempts(),&[60000,120000,600001]);}
#[test]fn stale_wait_plan_cannot_bypass_new_attempt_or_new_auth_marker(){let b=prepare_attempt(&RecoveryBudget::new(0).unwrap(),0,None).unwrap();assert_eq!(next_attempt(&b,1000,None).unwrap(),60000);let newer=prepare_attempt(&b,60000,None).unwrap();assert_eq!(prepare_attempt(&newer,60000,None),Err(RetryError::TooSoon));assert_eq!(prepare_attempt(&b,60000,Some(59000)),Err(RetryError::TooSoon));}
#[test]fn corrupted_or_regressed_durable_budget_is_never_reseeded(){let mut b=RecoveryBudget::new(1000).unwrap();b.record_attempt(1000).unwrap();assert_eq!(next_attempt(&b,999,None),Err(RetryError::Budget(BudgetError::ClockRegression)));let corrupt:RecoveryBudget=serde_json::from_value(serde_json::json!({"schemaVersion":2,"lastClockMs":1000,"attempts":[]})).unwrap();assert_eq!(next_attempt(&corrupt,1000,None),Err(RetryError::Budget(BudgetError::Schema)));assert_eq!(b.attempts(),&[1000]);}
#[test]fn future_auth_marker_and_boundary_overflow_fail_closed(){let b=RecoveryBudget::new(1000).unwrap();assert_eq!(next_attempt(&b,1000,Some(1001)),Err(RetryError::AuthClockRegression));assert_eq!(next_attempt(&b,1000,Some(MAXIMUM_CLOCK_MS+1)),Err(RetryError::AuthClockRange));let near=RecoveryBudget::new(MAXIMUM_CLOCK_MS).unwrap();assert_eq!(next_attempt(&near,MAXIMUM_CLOCK_MS,Some(MAXIMUM_CLOCK_MS)),Err(RetryError::AuthClockRange));}
#[test]fn success_does_not_reset_shared_outage_budget(){let initial=prepare_attempt(&RecoveryBudget::new(0).unwrap(),0,None).unwrap();let first_recovery=prepare_attempt(&initial,60000,Some(0)).unwrap();let second_recovery=prepare_attempt(&first_recovery,120000,Some(60000)).unwrap();assert_eq!(next_attempt(&second_recovery,180000,Some(120000)),Err(RetryError::Exhausted));}
